    if ((pb == NULL) || (sb == NULL) || (pi == NULL) || (si == NULL) || (out == NULL)) {
        return ADCS_E_NULL;
    }

    /* 2. Finite value check */
    if (!adcs_is_finite_vec3(pb) || !adcs_is_finite_vec3(sb) || 
        !adcs_is_finite_vec3(pi) || !adcs_is_finite_vec3(si)) {
        *out = adcs_mat3_identity();
        return ADCS_E_NOT_FINITE;
    }

    /* 3. Check for zero vectors in primary directions */
    if (adcs_vec3_norm(pb) <= ADCS_EPS_NORM) {
        *out = adcs_mat3_identity();
        return ADCS_E_DEGENERATE;
    }
    if (adcs_vec3_norm(pi) <= ADCS_EPS_NORM) {
        *out = adcs_mat3_identity();
        return ADCS_E_DEGENERATE;
    }

    /* 4. Construct Body Frame Basis (B) */
    /* First column: Normalized Primary Body Vector */
    norm_primary_body = adcs_vec3_scale(pb, 1.0 / adcs_vec3_norm(pb));
    b_basis.m[0][0] = norm_primary_body.x;
    b_basis.m[1][0] = norm_primary_body.y;
    b_basis.m[2][0] = norm_primary_body.z;

    /* Second column: Normalized Cross(Primary Body, Secondary Body) */
    cross_body = adcs_vec3_cross(pb, sb);
    norm_cross_body = adcs_vec3_norm(&cross_body);
    if (norm_cross_body <= ADCS_EPS_COLLINEAR) {
        *out = adcs_mat3_identity();
        return ADCS_E_DEGENERATE;
    }
    second_col_body = adcs_vec3_scale(&cross_body, 1.0 / norm_cross_body);
    b_basis.m[0][1] = second_col_body.x;
    b_basis.m[1][1] = second_col_body.y;
    b_basis.m[2][1] = second_col_body.z;

    /* Third column: Orthogonal completion via Cross(Col1, Col2) */
    third_col_body = adcs_vec3_cross(&norm_primary_body, &second_col_body);
    b_basis.m[0][2] = third_col_body.x;
    b_basis.m[1][2] = third_col_body.y;
    b_basis.m[2][2] = third_col_body.z;

    /* 5. Construct Inertial Frame Basis (R) */
    /* First column: Normalized Primary Inertial Vector */
    norm_primary_inertial = adcs_vec3_scale(pi, 1.0 / adcs_vec3_norm(pi));
    r_basis.m[0][0] = norm_primary_inertial.x;
    r_basis.m[1][0] = norm_primary_inertial.y;
    r_basis.m[2][0] = norm_primary_inertial.z;

    /* Second column: Normalized Cross(Primary Inertial, Secondary Inertial) */
    cross_inertial = adcs_vec3_cross(pi, si);
    norm_cross_inertial = adcs_vec3_norm(&cross_inertial);
    if (norm_cross_inertial <= ADCS_EPS_COLLINEAR) {
        *out = adcs_mat3_identity();
        return ADCS_E_DEGENERATE;
    }
    second_col_inertial = adcs_vec3_scale(&cross_inertial, 1.0 / norm_cross_inertial);
    r_basis.m[0][1] = second_col_inertial.x;
    r_basis.m[1][1] = second_col_inertial.y;
    r_basis.m[2][1] = second_col_inertial.z;

    /* Third column: Orthogonal completion via Cross(Col1, Col2) */
    third_col_inertial = adcs_vec3_cross(&norm_primary_inertial, &second_col_inertial);
    r_basis.m[0][2] = third_col_inertial.x;
    r_basis.m[1][2] = third_col_inertial.y;
    r_basis.m[2][2] = third_col_inertial.z;

    /* 6. Calculate Rotation Matrix C_bi = B * R_transpose */
    r_transpose = adcs_mat3_transpose(&r_basis);
    result = adcs_mat3_mul(&b_basis, &r_transpose);
    *out = result;

    return ADCS_OK;
}
